namespace sonder::inference::spec {

enum class SpecMode : std::uint8_t {
    kNone = 0,
    kNgramMod = 1,
    kDraftMtp = 2,
};

struct SpecTelemetry {
    std::uint64_t draft_proposed = 0;
    std::uint64_t draft_accepted = 0;
    std::uint64_t verify_batches = 0;
    std::uint64_t cooldown_skips = 0;

    double acceptance_ratio() const noexcept {
        return draft_proposed > 0
            ? static_cast<double>(draft_accepted) / static_cast<double>(draft_proposed)
            : 0.0;
    }
};

class AdaptiveDraftController {
public:
    AdaptiveDraftController(SpecMode mode, std::int32_t max_draft)
        : mode_(mode),
          configured_max_(std::clamp(max_draft, 0, 32)),
          current_max_(configured_max_ > 0 ? configured_max_ : (mode == SpecMode::kDraftMtp ? 3 : 8)) {}

    std::int32_t next_draft_budget() noexcept {
        if (mode_ == SpecMode::kNone || current_max_ <= 0) {
            return 0;
        }
        if (cooldown_remaining_ > 0) {
            --cooldown_remaining_;
            ++telemetry_.cooldown_skips;
            return 0;
        }
        return current_max_;
    }

    void record_step(std::int32_t proposed, std::int32_t accepted) noexcept {
        if (proposed <= 0) {
            return;
        }
        telemetry_.draft_proposed += static_cast<std::uint64_t>(proposed);
        telemetry_.draft_accepted += static_cast<std::uint64_t>(accepted);
        ++telemetry_.verify_batches;

        // Exponential moving average of acceptance ratio.
        const double step_acc = static_cast<double>(accepted) / static_cast<double>(proposed);
        ema_acceptance_ = 0.80 * ema_acceptance_ + 0.20 * step_acc;

        const std::int32_t ceiling = configured_max_ > 0
            ? configured_max_
            : (mode_ == SpecMode::kDraftMtp ? 3 : 8);

        if (ema_acceptance_ < 0.18 && telemetry_.verify_batches >= 6) {
            if (current_max_ > 2) {
                current_max_ /= 2;
            } else {
                // Pause drafting briefly during unpredictable open-ended prose
                // so rejected verification batches never regress decode tok/s.
                cooldown_remaining_ = 8;
            }
        } else if (ema_acceptance_ > 0.65 && current_max_ < ceiling) {
            current_max_ = std::min(ceiling, current_max_ + 1);
        }
    }

    const SpecTelemetry& telemetry() const noexcept { return telemetry_; }
    double ema_acceptance() const noexcept { return ema_acceptance_; }
    std::int32_t current_max() const noexcept { return current_max_; }

private:
    SpecMode mode_ = SpecMode::kNone;
    std::int32_t configured_max_ = 0;
    std::int32_t current_max_ = 0;
    std::int32_t cooldown_remaining_ = 0;
    double ema_acceptance_ = 0.50;
    SpecTelemetry telemetry_{};
};

// Hash-indexed 4-gram / 3-gram ring lookup table with O(1) incremental insert.
class NgramLookupTable {
public:
    static constexpr std::size_t kBuckets = 4096;

    void clear() noexcept {
        entries4_.fill(Entry{});
        entries3_.fill(Entry{});
    }

    void ingest(std::span<const std::int32_t> tokens, std::size_t start_pos = 0) noexcept {
        for (std::size_t i = start_pos; i < tokens.size(); ++i) {
            if (i >= 4) {
                const std::uint32_t h4 = hash4(tokens[i - 4], tokens[i - 3], tokens[i - 2], tokens[i - 1]);
                entries4_[h4 & (kBuckets - 1)] = Entry{.valid = true, .key_last = tokens[i - 1], .pos = static_cast<std::uint32_t>(i)};
            }
            if (i >= 3) {
                const std::uint32_t h3 = hash3(tokens[i - 3], tokens[i - 2], tokens[i - 1]);
                entries3_[h3 & (kBuckets - 1)] = Entry{.valid = true, .key_last = tokens[i - 1], .pos = static_cast<std::uint32_t>(i)};
            }
        }
    }

    std::vector<std::int32_t> draft(std::span<const std::int32_t> history, std::int32_t max_tokens) const {
        std::vector<std::int32_t> out;
        if (max_tokens <= 0 || history.size() < 4) {
            return out;
        }
        const std::size_t n = history.size();
        const std::uint32_t h4 = hash4(history[n - 4], history[n - 3], history[n - 2], history[n - 1]);
        const Entry& e4 = entries4_[h4 & (kBuckets - 1)];
        std::size_t match_pos = 0;
        if (e4.valid && e4.key_last == history[n - 1] && e4.pos >= 4 && e4.pos < n) {
            if (history[e4.pos - 4] == history[n - 4] &&
                history[e4.pos - 3] == history[n - 3] &&
                history[e4.pos - 2] == history[n - 2]) {
                match_pos = e4.pos;
            }
        }
        if (match_pos == 0) {
            const std::uint32_t h3 = hash3(history[n - 3], history[n - 2], history[n - 1]);
            const Entry& e3 = entries3_[h3 & (kBuckets - 1)];
            if (e3.valid && e3.key_last == history[n - 1] && e3.pos >= 3 && e3.pos < n) {
                if (history[e3.pos - 3] == history[n - 3] &&
                    history[e3.pos - 2] == history[n - 2]) {
                    match_pos = e3.pos;
                }
            }
        }
        if (match_pos > 0) {
            out.reserve(static_cast<std::size_t>(max_tokens));
            for (std::int32_t k = 0; k < max_tokens && (match_pos + static_cast<std::size_t>(k)) < n; ++k) {
                out.push_back(history[match_pos + static_cast<std::size_t>(k)]);
            }
        }
        return out;
    }

private:
    struct Entry {
        bool valid = false;
        std::int32_t key_last = 0;
        std::uint32_t pos = 0;
    };

    static constexpr std::uint32_t hash3(std::int32_t a, std::int32_t b, std::int32_t c) noexcept {
        std::uint32_t h = static_cast<std::uint32_t>(a) * 2654435761u;
        h = (h ^ static_cast<std::uint32_t>(b)) * 2246822519u;
        h = (h ^ static_cast<std::uint32_t>(c)) * 3266489917u;
        return h ^ (h >> 16);
    }

    static constexpr std::uint32_t hash4(std::int32_t a, std::int32_t b, std::int32_t c, std::int32_t d) noexcept {
        std::uint32_t h = hash3(a, b, c);
        h = (h ^ static_cast<std::uint32_t>(d)) * 668265263u;
        return h ^ (h >> 15);
    }

    std::array<Entry, kBuckets> entries4_{};
    std::array<Entry, kBuckets> entries3_{};
};

