namespace sonder::inference::http {

struct KeepAliveConfig {
    bool enabled = true;
    std::uint32_t idle_timeout_ms = 15000;
    std::size_t max_requests_per_connection = 256;
};

struct RequestFrameInfo {
    int http_minor = 1;
    bool client_requested_close = false;
    bool is_sse_stream = false;
    std::size_t unread_body_bytes = 0;
    bool write_ok = true;
};

inline bool should_keep_alive(
    const KeepAliveConfig& cfg,
    const RequestFrameInfo& req,
    bool server_stopping,
    std::size_t requests_served_on_socket) noexcept {
    if (!cfg.enabled || server_stopping) {
        return false;
    }
    if (req.http_minor < 1 || req.client_requested_close || req.is_sse_stream) {
        return false;
    }
    if (req.unread_body_bytes != 0 || !req.write_ok) {
        return false;
    }
    return requests_served_on_socket < cfg.max_requests_per_connection;
}

