class BoundedSuffixIndex {
public:
    static constexpr std::size_t kDefaultRingCapacity = 131072;
    static constexpr std::size_t kMinHybridEscalationLen = 6;
    static constexpr std::size_t kMaxBurstDraftTokens = 16;

    explicit BoundedSuffixIndex(std::size_t ring_capacity = kDefaultRingCapacity)
        : ring_capacity_(std::clamp<std::size_t>(ring_capacity, 4096, 262144)) {}

    void append_session_tokens(std::span<const std::int32_t> tokens) {
        for (std::int32_t tok : tokens) {
            if (ring_.size() >= ring_capacity_) {
                ring_.pop_front();
            }
            ring_.push_back(tok);
        }
    }

    // Find the longest suffix of `context` (up to `max_match_len`) occurring
    // earlier in either the active sequence or the bounded session ring buffer.
    // When match length >= kMinHybridEscalationLen, hybrid draft-mtp escalates
    // to a 6..16 token suffix burst rather than capping at MTP k=3.
    SuffixDraftProposal propose(
        std::span<const std::int32_t> context,
        std::size_t max_draft,
        std::size_t max_match_len = 32) const {
        SuffixDraftProposal best;
        if (context.size() < 3 || max_draft == 0) {
            return best;
        }
        const std::size_t n = context.size();
        const std::size_t cap_match = std::min(max_match_len, n - 1);
        const std::int32_t anchor = context[n - 1];
        for (std::size_t pos = n - 2; pos >= 1; --pos) {
            if (context[pos] != anchor) {
                if (pos == 1) break;
                continue;
            }
            std::size_t mlen = 1;
            while (mlen < cap_match && pos >= mlen &&
                   context[pos - mlen] == context[n - 1 - mlen]) {
                ++mlen;
            }
            if (mlen >= 3 && mlen > best.matched_suffix_len && (pos + 1) < n) {
                best.matched_suffix_len = mlen;
                best.tokens.clear();
                const std::size_t avail = std::min(max_draft, n - (pos + 1));
                best.tokens.reserve(avail);
                for (std::size_t k = 0; k < avail; ++k) {
                    best.tokens.push_back(context[pos + 1 + k]);
                }
                best.confidence = std::min(1.0, static_cast<double>(mlen) / 10.0);
            }
            if (pos == 1) break;
        }
        return best;
    }

private:
    std::size_t ring_capacity_ = kDefaultRingCapacity;
    std::deque<std::int32_t> ring_;
};

