struct RadixStateBlob {
    std::vector<std::int32_t> prefix_tokens;
    std::vector<std::uint8_t> serialized_kv_ssm;
    std::uint64_t lru_tick = 0;
};

class BoundedRadixL2Cache {
public:
    explicit BoundedRadixL2Cache(std::size_t budget_bytes)
        : budget_bytes_(budget_bytes) {}

    // Strict pre-allocation LRU eviction guarantees host RAM never spikes
    // above the configured `--cache-ram-mib` ceiling on 31 GiB workstations.
    bool insert(std::vector<std::int32_t> tokens, std::vector<std::uint8_t> blob) {
        if (budget_bytes_ == 0 || blob.empty() || blob.size() > budget_bytes_) {
            return false;
        }
        while (used_bytes_ + blob.size() > budget_bytes_ && !entries_.empty()) {
            evict_oldest();
        }
        used_bytes_ += blob.size();
        entries_.push_back(RadixStateBlob{
            .prefix_tokens = std::move(tokens),
            .serialized_kv_ssm = std::move(blob),
            .lru_tick = ++clock_,
        });
        return true;
    }

    const RadixStateBlob* find_longest_prefix(std::span<const std::int32_t> prompt) {
        RadixStateBlob* best = nullptr;
        std::size_t best_len = 0;
        for (auto& e : entries_) {
            const std::size_t lim = std::min(e.prefix_tokens.size(), prompt.size());
            std::size_t lcp = 0;
            while (lcp < lim && e.prefix_tokens[lcp] == prompt[lcp]) {
                ++lcp;
            }
            if (lcp >= 32 && lcp == e.prefix_tokens.size() && lcp > best_len) {
                best_len = lcp;
                best = &e;
            }
        }
        if (best) {
            best->lru_tick = ++clock_;
        }
        return best;
    }

    std::size_t used_bytes() const noexcept { return used_bytes_; }
    std::size_t budget_bytes() const noexcept { return budget_bytes_; }

private:
    void evict_oldest() {
        auto it = std::min_element(
            entries_.begin(), entries_.end(),
            [](const RadixStateBlob& a, const RadixStateBlob& b) {
                return a.lru_tick < b.lru_tick;
            });
        if (it != entries_.end()) {
            used_bytes_ -= it->serialized_kv_ssm.size();
            entries_.erase(it);
        }
    }

    std::size_t budget_bytes_ = 0;
    std::size_t used_bytes_ = 0;
    std::uint64_t clock_ = 0;
    std::vector<RadixStateBlob> entries_;
};

